"use client";

import { FormEvent, useEffect, useMemo, useRef, useState, type ReactNode } from "react";
import { mockProspects } from "@/lib/mock-data";
import { neglectedProspects } from "@/lib/neglected";
import { pipelineStages, type PipelineStage, type Prospect } from "@/lib/types";

type View = "pipeline" | "agenda" | "alerts";
type CalendarViewMode = "month" | "week" | "day";
type GoogleStatus = { configured: boolean; connected: boolean; scopes: string[]; missing?: string[]; redirectUri?: string };
type DataSource = "demo" | "excel-local" | "error";
type CalendarEvent = { id: string; subject?: string; bodyPreview?: string; allDay?: boolean; start?: { date?: string; dateTime?: string }; end?: { date?: string; dateTime?: string }; webLink?: string; onlineMeeting?: { joinUrl?: string } };
type Filters = { stage: string; priority: string; category: string; industry: string; source: string; location: string; followUp: string; waitingReason: string };
type CommandItem = { kind: "prospect"; label: string; meta?: string; prospect: Prospect } | { kind: "navigation"; label: string; meta?: string; view: View };

const stageLabels: Record<PipelineStage, string> = { "clientes recibidos": "Recibidos", "clientes contactados": "Contactados", "clientes interesados": "Interesados", "clientes en espera": "En espera", "clientes no interesados": "No interesados" };
const stageColors: Record<PipelineStage, string> = { "clientes recibidos": "#8793a8", "clientes contactados": "#5577df", "clientes interesados": "#22a184", "clientes en espera": "#e2a83a", "clientes no interesados": "#dc6d6d" };
const priorityRank = { alta: 0, media: 1, baja: 2 };
const emptyFilters: Filters = { stage: "todas", priority: "todas", category: "todas", industry: "todas", source: "todas", location: "", followUp: "todas", waitingReason: "" };
const weekDays = ["L", "M", "M", "J", "V", "S", "D"];
const countryCodes = [{ code: "+52", country: "México" }, { code: "+1", country: "Estados Unidos / Canadá" }, { code: "+34", country: "España" }, { code: "+44", country: "Reino Unido" }, { code: "+49", country: "Alemania" }, { code: "+33", country: "Francia" }, { code: "+39", country: "Italia" }, { code: "+54", country: "Argentina" }, { code: "+55", country: "Brasil" }, { code: "+56", country: "Chile" }, { code: "+57", country: "Colombia" }, { code: "+58", country: "Venezuela" }, { code: "+591", country: "Bolivia" }, { code: "+593", country: "Ecuador" }, { code: "+595", country: "Paraguay" }, { code: "+598", country: "Uruguay" }, { code: "+501", country: "Belice" }, { code: "+502", country: "Guatemala" }, { code: "+503", country: "El Salvador" }, { code: "+504", country: "Honduras" }, { code: "+505", country: "Nicaragua" }, { code: "+506", country: "Costa Rica" }, { code: "+507", country: "Panamá" }, { code: "+51", country: "Perú" }];
const classificationRules = [
  { label: "Transportistas", terms: ["transportist", "transportadora", "transporte"] },
  { label: "Servicios portuarios", terms: ["servicio portuario", "servicios portuarios", "portuario", "consignataria"] },
  { label: "Agencias navieras", terms: ["agencia naviera", "agencias navieras", "naviera"] },
  { label: "Tour operadores", terms: ["tour operador", "tour operators", "operador turistico"] },
  { label: "Agencias de viajes", terms: ["agencia de viajes", "agencias de viajes"] },
  { label: "Exportadoras", terms: ["exportadora", "exportador", "exportacion"] },
  { label: "Hoteles", terms: ["hotel", "hoteles", "hospedaje"] },
  { label: "Mariscos", terms: ["marisco", "mariscos", "pesquera", "acuicola"] },
  { label: "IMMEX / Importadores", terms: ["immex", "imex", "importador", "importadora", "comercio exterior"] },
  { label: "Agroindustriales", terms: ["agroindustrial", "agroindustria", "agricola"] },
  { label: "Manufactura", terms: ["manufactura", "manufacturera", "fabricacion", "planta"] },
  { label: "Clientes potenciales", terms: ["clientes potenciales", "cliente potencial"] },
] as const;
const classificationLabels = classificationRules.map((rule) => rule.label);
type IconName = "grid" | "calendar" | "alert" | "panel" | "search" | "sliders" | "refresh" | "plus" | "logout";
const iconPaths: Record<IconName, ReactNode> = {
  grid: <><rect x="4" y="4" width="6" height="6" rx="1" /><rect x="14" y="4" width="6" height="6" rx="1" /><rect x="4" y="14" width="6" height="6" rx="1" /><rect x="14" y="14" width="6" height="6" rx="1" /></>,
  calendar: <><rect x="3.5" y="5" width="17" height="16" rx="2" /><path d="M7 3v4M17 3v4M4 9.5h16" /></>,
  alert: <><path d="M12 4 3.8 19h16.4L12 4Z" /><path d="M12 9v5M12 17h.01" /></>,
  panel: <><rect x="3" y="4" width="18" height="16" rx="2" /><path d="M8 4v16M14 10l3 3-3 3" /></>,
  search: <><circle cx="10.8" cy="10.8" r="6.5" /><path d="m16 16 4.5 4.5" /></>,
  sliders: <><path d="M4 6h16M4 12h16M4 18h16" /><circle cx="9" cy="6" r="2" /><circle cx="15" cy="12" r="2" /><circle cx="11" cy="18" r="2" /></>,
  refresh: <><path d="M20 11a8 8 0 0 0-14.6-4L4 9" /><path d="M4 4v5h5M4 13a8 8 0 0 0 14.6 4L20 15" /><path d="M20 20v-5h-5" /></>,
  plus: <><path d="M12 5v14M5 12h14" /></>,
  logout: <><path d="M10 5H5v14h5M14 8l4 4-4 4M18 12H9" /></>,
};
function UiIcon({ name, size = 18 }: { name: IconName; size?: number }) { return <svg aria-hidden="true" className="ui-icon" width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">{iconPaths[name]}</svg>; }

function formatDate(date?: string) { if (!date) return "Sin fecha"; return new Intl.DateTimeFormat("es-MX", { day: "2-digit", month: "short" }).format(new Date(`${date.length === 10 ? `${date}T12:00:00` : date}`)); }
function formatDateTime(date?: string) { if (!date) return "Sin fecha"; return new Intl.DateTimeFormat("es-MX", { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" }).format(new Date(date)); }
function initials(company: string) { return company.split(/\s+/).slice(0, 2).map((part) => part[0]).join("").toUpperCase(); }
function priorityLabel(priority: Prospect["priority"]) { return priority === "alta" ? "Alta" : priority === "media" ? "Media" : "Baja"; }
function dateOnly(value?: string) { return value?.slice(0, 10) ?? ""; }
function formatPhone(phone?: string) { const value = phone?.replace(/^\s+|\s+$/g, ""); if (!value) return ""; if (value.startsWith("+")) return value; const parsed = splitPhone(value); return `${parsed.countryCode} ${parsed.number}`.trim(); }
function splitPhone(phone?: string) { const raw = phone?.trim() ?? ""; if (!raw) return { countryCode: "+52", number: "" }; const match = countryCodes.find(({ code }) => { const digits = code.slice(1); return raw.startsWith(code) || raw.startsWith(`00${digits}`) || raw.startsWith(`${digits} `) || raw.startsWith(`${digits}-`); }); if (!match) return { countryCode: "+52", number: raw }; const prefix = match.code; const digits = prefix.slice(1); const number = raw.startsWith(prefix) ? raw.slice(prefix.length).trim() : raw.startsWith(`00${digits}`) ? raw.slice(digits.length + 2).trim() : raw.slice(digits.length).replace(/^[-\s]+/, "").trim(); return { countryCode: prefix, number }; }
function storedPhone(countryCode: string, number: string) { const value = number.trim(); if (!value) return undefined; if (value.startsWith("+")) return value; if (value.startsWith("00")) return `+${value.slice(2)}`; const digits = countryCode.replace("+", ""); return `${countryCode} ${value.replace(new RegExp(`^${digits}[\\s-]+`), "")}`; }
function normalizedText(value?: string) { return (value ?? "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase(); }
function prospectCategory(prospect: Prospect) { const text = normalizedText([prospect.industry, prospect.source, prospect.notes, prospect.tradeName, prospect.company].filter(Boolean).join(" ")); return classificationRules.find((rule) => rule.terms.some((term) => text.includes(normalizedText(term))))?.label ?? "Por clasificar"; }
function searchableProspectText(prospect: Prospect) { return [prospect.company, prospect.tradeName, prospect.contact, prospect.email, prospect.phone, prospect.website, prospect.location, prospect.industry, prospect.waitingReason, prospect.notes, prospect.source].filter(Boolean).join(" ").toLowerCase(); }
function isFollowUpOverdue(prospect: Prospect, today: string) { return Boolean(prospect.nextFollowUp && dateOnly(prospect.nextFollowUp) < today && (!prospect.lastInteraction || dateOnly(prospect.lastInteraction) < dateOnly(prospect.nextFollowUp))); }
function calendarDays(year: number, month: number) { const firstDay = (new Date(year, month, 1).getDay() + 6) % 7; const daysInMonth = new Date(year, month + 1, 0).getDate(); return [...Array(firstDay).fill(null), ...Array.from({ length: daysInMonth }, (_, index) => index + 1)]; }
function nextHourInput(value: string) { const date = new Date(`${value}:00`); date.setHours(date.getHours() + 1); const pad = (number: number) => String(number).padStart(2, "0"); return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`; }
function cleanContactName(value?: string) { const contact = value?.replace(/\s+/g, " ").trim(); return contact && !/@|https?:\/\/|tel[eé]f|correo|e-?mail|sitio/i.test(contact) ? contact : undefined; }
function meetingSubject(prospect?: Prospect) { if (!prospect) return "Nueva reunión"; return [formatPhone(prospect.phone), prospect.tradeName || prospect.company, cleanContactName(prospect.contact)].filter(Boolean).join(" · "); }
function meetingDescription(prospect?: Prospect) {
  if (!prospect) return "";
  const company = prospect.tradeName && prospect.tradeName !== prospect.company ? `${prospect.tradeName} · ${prospect.company}` : prospect.company;
  return [
    `Empresa: ${company}`,
    cleanContactName(prospect.contact) ? `Contacto: ${cleanContactName(prospect.contact)}` : "",
    prospect.phone ? `Teléfono: ${formatPhone(prospect.phone)}` : "",
    prospect.email ? `Correo: ${prospect.email}` : "",
    prospect.website ? `Sitio web: ${prospect.website}` : "",
    prospect.location ? `Ubicación: ${prospect.location}` : "",
    prospect.industry ? `Giro: ${prospect.industry}` : "",
    prospect.waitingReason ? `Motivo de espera: ${prospect.waitingReason}` : "",
    prospect.notes ? `Notas y seguimiento:\n${prospect.notes}` : "",
    prospect.nextFollowUp ? `Próximo seguimiento registrado: ${formatDate(prospect.nextFollowUp)}` : "",
  ].filter(Boolean).join("\n");
}

export default function Home() {
  const [view, setView] = useState<View>("pipeline");
  const [query, setQuery] = useState("");
  const [filters, setFilters] = useState<Filters>(emptyFilters);
  const [filtersOpen, setFiltersOpen] = useState(false);
  const [selected, setSelected] = useState<Prospect | null>(null);
  const [newProspectOpen, setNewProspectOpen] = useState(false);
  const [editing, setEditing] = useState<Prospect | null>(null);
  const [prospects, setProspects] = useState<Prospect[]>(mockProspects);
  const [dataSource, setDataSource] = useState<DataSource>("demo");
  const [dragOverStage, setDragOverStage] = useState<PipelineStage | null>(null);
  const [today] = useState(() => new Date().toISOString().slice(0, 10));
  const [meetingOpen, setMeetingOpen] = useState(false);
  const [google, setGoogle] = useState<GoogleStatus>({ configured: false, connected: false, scopes: [] });
  const [events, setEvents] = useState<CalendarEvent[]>([]);
  const [calendarMonth, setCalendarMonth] = useState(() => new Date(new Date().getFullYear(), new Date().getMonth(), 1));
  const [meetingDate, setMeetingDate] = useState(() => new Date().toISOString().slice(0, 10));
  const [meetingStart, setMeetingStart] = useState("");
  const [meetingEnd, setMeetingEnd] = useState("");
  const [googleNotice, setGoogleNotice] = useState<{ kind: "success" | "warning" | "error"; text: string } | null>(null);
  const [authReady, setAuthReady] = useState(false);
  const [demoMode, setDemoMode] = useState(false);
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [sidebarHovered, setSidebarHovered] = useState(false);
  const [commandOpen, setCommandOpen] = useState(false);
  const [commandQuery, setCommandQuery] = useState("");
  const [commandIndex, setCommandIndex] = useState(0);
  const sidebarCloseTimer = useRef<number | null>(null);

  useEffect(() => {
    const demoTimer = window.setTimeout(() => setDemoMode(window.localStorage.getItem("vpa_demo_mode") === "1"), 0);
    fetch("/api/google/status").then((response) => response.json()).then(setGoogle).catch(() => undefined).finally(() => setAuthReady(true));
    const params = new URLSearchParams(window.location.search);
    const timeoutId = window.setTimeout(() => {
      const returnedView = params.get("view");
      if (returnedView === "pipeline" || returnedView === "agenda" || returnedView === "alerts") setView(returnedView);
      const result = params.get("google");
      if (result === "missing") setGoogleNotice({ kind: "warning", text: "Google todavía no está configurado. Agrega GOOGLE_CLIENT_ID y GOOGLE_CLIENT_SECRET en .env.local y reinicia localhost." });
      if (result === "connected") setGoogleNotice({ kind: "success", text: "Cuenta de Google conectada. Ya puedes consultar tu calendario y crear eventos con Google Meet." });
      if (result === "error") setGoogleNotice({ kind: "error", text: `No se pudo conectar Google: ${params.get("detail") || "la autorización fue cancelada."}` });
      if (result) window.history.replaceState({}, "", "/");
    }, 0);
    return () => { window.clearTimeout(timeoutId); window.clearTimeout(demoTimer); };
  }, []);
  useEffect(() => { const timer = window.setTimeout(() => { if (window.localStorage.getItem("vpa_sidebar_collapsed") === "1") setSidebarCollapsed(true); }, 0); return () => window.clearTimeout(timer); }, []);
  useEffect(() => { fetch("/api/prospects").then(async (response) => { if (!response.ok) throw new Error("No se encontró el staging local."); return response.json() as Promise<{ items?: Prospect[] }>; }).then((data) => { if (data.items?.length) { setProspects(data.items); setDataSource("excel-local"); } }).catch(() => setDataSource("error")); }, []);
  useEffect(() => { if (view !== "agenda" || !google.connected) return; const start = new Date(calendarMonth.getFullYear() - 1, calendarMonth.getMonth(), 1).toISOString(); const end = new Date(calendarMonth.getFullYear() + 1, calendarMonth.getMonth() + 1, 0, 23, 59, 59).toISOString(); fetch(`/api/google/calendar?start=${encodeURIComponent(start)}&end=${encodeURIComponent(end)}`).then(async (response) => { const data = await response.json(); if (!response.ok) throw new Error(data.error || "No se pudo sincronizar Google Calendar."); return data; }).then((data) => setEvents(data.value ?? [])).catch((error) => setGoogleNotice({ kind: "error", text: error instanceof Error ? error.message : "No se pudo sincronizar Google Calendar." })); }, [calendarMonth, google.connected, view]);
  const industries = useMemo(() => ["todas", ...new Set(prospects.map((prospect) => prospect.industry))], [prospects]);
  const sources = useMemo(() => ["todas", ...new Set(prospects.map((prospect) => prospect.source))], [prospects]);
  const categories = useMemo(() => ["todas", ...classificationLabels, "Por clasificar"], []);
  const activeFilterCount = Object.entries(filters).filter(([key, value]) => value && value !== "todas" && key !== "location").length + (filters.location ? 1 : 0);
  const filtered = useMemo(() => prospects.filter((prospect) => {
    const matchesQuery = searchableProspectText(prospect).includes(query.trim().toLowerCase());
    const matchesStage = filters.stage === "todas" || prospect.stage === filters.stage;
    const matchesPriority = filters.priority === "todas" || prospect.priority === filters.priority;
    const matchesCategory = filters.category === "todas" || prospectCategory(prospect) === filters.category;
    const matchesIndustry = filters.industry === "todas" || prospect.industry === filters.industry;
    const matchesSource = filters.source === "todas" || prospect.source === filters.source;
    const matchesLocation = !filters.location || (prospect.location ?? "").toLowerCase().includes(filters.location.toLowerCase());
    const matchesFollowUp = filters.followUp === "todas" || (filters.followUp === "con-seguimiento" ? Boolean(prospect.nextFollowUp) : !prospect.nextFollowUp);
    const matchesWaiting = !filters.waitingReason || (prospect.waitingReason ?? "").toLowerCase().includes(filters.waitingReason.toLowerCase());
    return matchesQuery && matchesStage && matchesPriority && matchesCategory && matchesIndustry && matchesSource && matchesLocation && matchesFollowUp && matchesWaiting;
  }), [filters, prospects, query]);
  const sorted = (items: Prospect[]) => [...items].sort((a, b) => priorityRank[a.priority] - priorityRank[b.priority] || (a.nextFollowUp ?? "9999").localeCompare(b.nextFollowUp ?? "9999") || a.company.localeCompare(b.company));
  const count = (stage: PipelineStage) => filtered.filter((prospect) => prospect.stage === stage).length;
  const alertItems = useMemo(() => neglectedProspects(prospects), [prospects]);
  const commandItems = useMemo<CommandItem[]>(() => {
    const term = commandQuery.trim().toLowerCase();
    const prospectItems = prospects.filter((prospect) => !term || searchableProspectText(prospect).includes(term)).slice(0, 8).map((prospect) => ({ kind: "prospect" as const, label: prospect.tradeName ?? prospect.company, meta: prospect.contact || prospect.company, prospect }));
    const navigationItems = ([
      { view: "pipeline" as View, label: "Embudo", meta: "Gestión comercial" },
      { view: "agenda" as View, label: "Agenda", meta: "Calendario" },
      { view: "alerts" as View, label: "Alertas", meta: "Seguimiento" },
    ]).filter((item) => !term || `${item.label} ${item.meta}`.toLowerCase().includes(term)).map((item) => ({ kind: "navigation" as const, ...item }));
    return [...prospectItems, ...navigationItems];
  }, [commandQuery, prospects]);
  useEffect(() => {
    function handleGlobalKeyDown(event: KeyboardEvent) {
      if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "k") { event.preventDefault(); setCommandOpen((open) => !open); setCommandQuery(""); setCommandIndex(0); return; }
      if (!commandOpen) return;
      if (event.key === "Escape") { event.preventDefault(); setCommandOpen(false); return; }
      if (event.key === "ArrowDown") { event.preventDefault(); setCommandIndex((index) => commandItems.length ? (index + 1) % commandItems.length : 0); return; }
      if (event.key === "ArrowUp") { event.preventDefault(); setCommandIndex((index) => commandItems.length ? (index - 1 + commandItems.length) % commandItems.length : 0); return; }
      if (event.key === "Enter" && commandItems[commandIndex]) { event.preventDefault(); selectCommandItem(commandItems[commandIndex]); }
    }
    window.addEventListener("keydown", handleGlobalKeyDown);
    return () => window.removeEventListener("keydown", handleGlobalKeyDown);
  }, [commandIndex, commandItems, commandOpen]);
  const title = view === "pipeline" ? "Embudo comercial" : view === "agenda" ? "Agenda" : "Clientes descuidados";
  const sidebarExpanded = !sidebarCollapsed || sidebarHovered;

  function connectGoogle() {
    if (!google.configured) { setView("agenda"); setGoogleNotice({ kind: "warning", text: `Faltan ${(google.missing ?? ["GOOGLE_CLIENT_ID", "GOOGLE_CLIENT_SECRET"]).join(" y ")}. Configúralas en .env.local y registra ${google.redirectUri || "http://localhost:3000/api/google/callback"} en Google Cloud.` }); return; }
    // eslint-disable-next-line @next/next/no-location-assign-relative-destination
    window.location.href = `/api/google/login?returnTo=${encodeURIComponent(view)}`;
  }
  function enterDemo() { window.localStorage.setItem("vpa_demo_mode", "1"); setDemoMode(true); setGoogleNotice({ kind: "success", text: "Modo demo activo. Puedes mostrar el embudo y los datos locales sin conectar Google todavía." }); }
  async function logout() { await fetch("/api/google/logout", { method: "POST" }); window.localStorage.removeItem("vpa_demo_mode"); setDemoMode(false); setGoogle((current) => ({ ...current, connected: false })); setEvents([]); setView("pipeline"); }
  function resetFilters() { setFilters(emptyFilters); setQuery(""); }
  function toggleSidebar() { setSidebarCollapsed((collapsed) => { const next = !collapsed; window.localStorage.setItem("vpa_sidebar_collapsed", next ? "1" : "0"); if (next) setSidebarHovered(false); return next; }); }
  function handleSidebarEnter() { if (sidebarCloseTimer.current) window.clearTimeout(sidebarCloseTimer.current); setSidebarHovered(true); }
  function handleSidebarLeave() { if (sidebarCloseTimer.current) window.clearTimeout(sidebarCloseTimer.current); sidebarCloseTimer.current = window.setTimeout(() => setSidebarHovered(false), 320); }
  function selectCommandItem(item: CommandItem) { setCommandOpen(false); setCommandQuery(""); setCommandIndex(0); if (item.kind === "navigation") setView(item.view); else { setView("pipeline"); setSelected(item.prospect); } }
  function openMeeting(date?: string) { const baseDate = date?.slice(0, 10) || new Date().toISOString().slice(0, 10); const start = date && date.length > 10 ? date : `${baseDate}T09:00`; setMeetingDate(baseDate); setMeetingStart(start); setMeetingEnd(nextHourInput(start)); setMeetingOpen(true); }
  function moveProspect(prospectId: string, stage: PipelineStage) { setProspects((current) => current.map((prospect) => prospect.id === prospectId ? { ...prospect, stage } : prospect)); setDragOverStage(null); }
  async function createMeeting(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); const form = new FormData(event.currentTarget);
    const allDay = form.get("allDay") === "on"; const date = String(form.get("date") || meetingDate); const start = String(form.get("start") || meetingStart); const end = String(form.get("end") || meetingEnd);
    if (allDay && !date) { setGoogleNotice({ kind: "error", text: "Selecciona el día de la reunión." }); return; }
    if (!allDay && (!start || !end || new Date(end) <= new Date(start))) { setGoogleNotice({ kind: "error", text: "La hora de fin debe ser posterior a la hora de inicio. Elige, por ejemplo, una reunión de 60 minutos." }); return; }
    const response = await fetch("/api/google/events", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ subject: form.get("subject"), allDay, date, start, end, attendeeEmail: form.get("attendeeEmail"), body: form.get("body") }) });
    if (response.ok) { setMeetingOpen(false); setView("agenda"); setGoogleNotice({ kind: "success", text: "Evento creado en Google Calendar con enlace de Google Meet." }); }
    else { const data = await response.json().catch(() => ({})); setGoogleNotice({ kind: "error", text: data.error || "No se pudo crear el evento. Revisa la conexión de Google y los permisos de Calendar." }); }
  }
  async function moveCalendarEvent(eventId: string, date: string, time?: string) {
    const event = events.find((item) => item.id === eventId); if (!event) return;
    const payload = event.allDay ? { allDay: true, date } : { allDay: false, start: `${date}T${time || event.start?.dateTime?.slice(11, 16) || "09:00"}`, end: `${date}T${time ? `${String(Number(time.slice(0, 2)) + 1).padStart(2, "0")}:00` : event.end?.dateTime?.slice(11, 16) || "10:00"}` };
    const response = await fetch(`/api/google/events/${encodeURIComponent(eventId)}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) });
    if (response.ok) { const updated = await response.json(); setEvents((current) => current.map((item) => item.id === eventId ? updated : item)); } else { const data = await response.json().catch(() => ({})); setGoogleNotice({ kind: "error", text: data.error || "No se pudo mover el evento en Google Calendar." }); }
  }
  function addProspect(prospect: Prospect) { setProspects((current) => current.some((item) => item.id === prospect.id) ? current.map((item) => item.id === prospect.id ? prospect : item) : [...current, prospect]); setView("pipeline"); setNewProspectOpen(false); setEditing(null); }

  if (!authReady) return <AuthScreen loading />;
  if (!google.connected && !demoMode) return <AuthScreen configured={google.configured} missing={google.missing} redirectUri={google.redirectUri} notice={googleNotice} onConnect={connectGoogle} onDemo={enterDemo} />;

  return <main className="app-shell">
    <Sidebar view={view} onNavigate={setView} prospectCount={prospects.length} agendaCount={prospects.filter((p) => p.nextFollowUp).length} alertCount={alertItems.length} googleConnected={google.connected} demoMode={demoMode} onConnect={connectGoogle} onLogout={logout} collapsed={sidebarCollapsed} expanded={sidebarExpanded} onToggle={toggleSidebar} onMouseEnter={handleSidebarEnter} onMouseLeave={handleSidebarLeave} />
    <section className="content"><header className="topbar"><div><div className="breadcrumb">VPA CRM <span>/</span> Gestión comercial</div><h1>{title}</h1></div><div className="topbar-actions"><span className="privacy-pill">{dataSource === "excel-local" ? `Excel local · ${prospects.length.toLocaleString("es-MX")}` : dataSource === "error" ? "Excel local no disponible" : "Datos demo · local"}</span><button className="primary-button" onClick={() => setNewProspectOpen(true)}><UiIcon name="plus" size={16} /> Nuevo prospecto</button></div></header><div className="content-body">{googleNotice && <div className={`microsoft-notice ${googleNotice.kind}`} role="status"><span>{googleNotice.kind === "success" ? "✓" : googleNotice.kind === "error" ? "!" : "i"}</span><p>{googleNotice.text}</p><button type="button" onClick={() => setGoogleNotice(null)}>×</button></div>}
      {view === "pipeline" && <><section className="hero-row"><div><p className="hero-title">Seguimiento sin cabos sueltos.</p><p className="hero-subtitle">Prioridad, contexto y próxima acción en una sola vista.</p></div><div className="summary-row"><div><small>Visibles</small><strong>{filtered.length.toLocaleString("es-MX")}</strong></div><div><small>Alta prioridad</small><strong className="red">{filtered.filter((p) => p.priority === "alta").length.toLocaleString("es-MX")}</strong></div><div><small>Seguimientos vencidos</small><strong className="red">{filtered.filter((p) => isFollowUpOverdue(p, today)).length.toLocaleString("es-MX")}</strong></div></div></section><section className="toolbar"><label className="search-field"><UiIcon name="search" size={17} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Busca empresa, teléfono, correo, contacto o ciudad" /><kbd>Ctrl K</kbd></label><button className={activeFilterCount ? "filter-button selected" : "filter-button"} onClick={() => setFiltersOpen(true)}><UiIcon name="sliders" size={16} /><span>Filtros</span>{activeFilterCount > 0 && <em>{activeFilterCount}</em>}</button><button className="icon-button" title="Restablecer filtros" aria-label="Restablecer filtros" onClick={resetFilters}><UiIcon name="refresh" size={16} /></button><span className="result-count">{filtered.length.toLocaleString("es-MX")} resultados · Arrastra para cambiar de etapa</span></section><section className="board">{pipelineStages.map((stage) => <div className={dragOverStage === stage ? "column drop-target" : "column"} key={stage} onDragOver={(event) => { event.preventDefault(); setDragOverStage(stage); }} onDragLeave={() => setDragOverStage(null)} onDrop={(event) => { event.preventDefault(); const prospectId = event.dataTransfer.getData("text/plain"); if (prospectId) moveProspect(prospectId, stage); }}><div className="column-head"><span className="stage-marker" style={{ background: stageColors[stage] }} /><span>{stageLabels[stage]}</span><b>{count(stage).toLocaleString("es-MX")}</b></div><div className="cards">{sorted(filtered.filter((prospect) => prospect.stage === stage)).map((prospect) => <ProspectCard key={prospect.id} prospect={prospect} overdue={isFollowUpOverdue(prospect, today)} onClick={() => setSelected(prospect)} onDragStart={(event) => event.dataTransfer.setData("text/plain", prospect.id)} onDragEnd={() => setDragOverStage(null)} />)}{count(stage) === 0 && <div className="empty-column">No hay prospectos aquí</div>}</div></div>)}</section></>}
      {view === "agenda" && <AgendaView connected={google.connected} events={events} month={calendarMonth} onConnect={connectGoogle} onCreate={openMeeting} onMonthChange={setCalendarMonth} onMoveEvent={moveCalendarEvent} />}
      {view === "alerts" && <AlertsView connected={google.connected} alerts={alertItems} onConnect={connectGoogle} />}
    </div></section>
    {commandOpen && <CommandPalette query={commandQuery} onQueryChange={(value) => { setCommandQuery(value); setCommandIndex(0); }} items={commandItems} activeIndex={commandIndex} onActiveIndex={setCommandIndex} onSelect={selectCommandItem} onClose={() => setCommandOpen(false)} />}

    {(newProspectOpen || editing) && <NewProspectModal initialProspect={editing ?? undefined} onClose={() => { setNewProspectOpen(false); setEditing(null); }} onCreate={addProspect} industries={industries.filter((item) => item !== "todas")} />}
    {filtersOpen && <div className="overlay" onClick={() => setFiltersOpen(false)}><aside className="filter-panel" onClick={(event) => event.stopPropagation()}><div className="panel-heading"><div><div className="eyebrow">Refinar resultados</div><h2>Todos los filtros</h2><p className="filter-intro">Clasifica por etapa, prioridad y giro comercial.</p></div><button className="close-button" onClick={() => setFiltersOpen(false)}>×</button></div><div className="filter-grid"><label>Etapa<select value={filters.stage} onChange={(event) => setFilters((f) => ({ ...f, stage: event.target.value }))}><option value="todas">Todas</option>{pipelineStages.map((stage) => <option key={stage} value={stage}>{stageLabels[stage]}</option>)}</select></label><label>Prioridad<select value={filters.priority} onChange={(event) => setFilters((f) => ({ ...f, priority: event.target.value }))}><option value="todas">Todas</option><option value="alta">Alta</option><option value="media">Media</option><option value="baja">Baja</option></select></label><label>Tipo de cliente / giro<select value={filters.category} onChange={(event) => setFilters((f) => ({ ...f, category: event.target.value }))}>{categories.map((item) => <option key={item} value={item}>{item === "todas" ? "Todos los tipos" : item}</option>)}</select></label><label>Industria original<select value={filters.industry} onChange={(event) => setFilters((f) => ({ ...f, industry: event.target.value }))}>{industries.map((item) => <option key={item} value={item}>{item === "todas" ? "Todas" : item}</option>)}</select></label><label>Fuente<select value={filters.source} onChange={(event) => setFilters((f) => ({ ...f, source: event.target.value }))}>{sources.map((item) => <option key={item} value={item}>{item === "todas" ? "Todas" : item}</option>)}</select></label><label>Ubicación<input value={filters.location} onChange={(event) => setFilters((f) => ({ ...f, location: event.target.value }))} placeholder="Ciudad o estado" /></label><label>Seguimiento<select value={filters.followUp} onChange={(event) => setFilters((f) => ({ ...f, followUp: event.target.value }))}><option value="todas">Todos</option><option value="con-seguimiento">Con fecha</option><option value="sin-seguimiento">Sin fecha</option></select></label><label className="full-filter">Motivo de espera<input value={filters.waitingReason} onChange={(event) => setFilters((f) => ({ ...f, waitingReason: event.target.value }))} placeholder="Ej. esperar a que seamos banco" /></label></div><div className="filter-footer"><button className="ghost-button" onClick={resetFilters}>Limpiar</button><button className="primary-button" onClick={() => setFiltersOpen(false)}>Ver {filtered.length} resultados</button></div></aside></div>}
    {selected && <div className="overlay" onClick={() => setSelected(null)}><aside className="detail-panel" onClick={(event) => event.stopPropagation()}><div className="panel-heading"><div><div className="eyebrow">Ficha de prospecto</div><h2>{selected.tradeName ?? selected.company}</h2></div><button className="close-button" onClick={() => setSelected(null)}>×</button></div><div className="detail-status"><span className="stage-badge" style={{ color: stageColors[selected.stage] }}>{stageLabels[selected.stage]}</span><span className={`priority priority-${selected.priority}`}>{priorityLabel(selected.priority)}</span>{isFollowUpOverdue(selected, today) && <span className="overdue-badge">Seguimiento vencido</span>}</div><div className="quick-actions"><button onClick={() => openMeeting(selected.nextFollowUp ? `${selected.nextFollowUp}T09:00` : undefined)}>◷ Agendar en Google</button></div><DetailSection title="Empresa"><DetailRow label="Razón social" value={selected.company} /><DetailRow label="Industria" value={selected.industry} /><DetailRow label="Ubicación" value={selected.location ?? "Sin ubicación"} /><DetailRow label="Fuente" value={selected.source} />{selected.recordCount && selected.recordCount > 1 && <><DetailRow label="Registros unidos" value={String(selected.recordCount)} /><DetailRow label="Ubicaciones" value={String(selected.locationCount ?? 0)} /></>}</DetailSection><DetailSection title="Contacto"><DetailRow label="Persona" value={selected.contact ?? "Pendiente de identificar"} /><DetailRow label="Teléfono" value={formatPhone(selected.phone) || "Sin teléfono"} /><DetailRow label="Correo" value={selected.email ?? "Sin correo"} /><DetailRow label="Sitio web" value={selected.website ?? "Sin sitio web"} /></DetailSection><DetailSection title="Seguimiento"><p className="notes">{selected.notes ?? "Sin notas todavía."}</p>{selected.waitingReason && <div className="waiting-box"><strong>Motivo de espera</strong><span>{selected.waitingReason}</span></div>}{selected.nextFollowUp && <div className={isFollowUpOverdue(selected, today) ? "next-date overdue-date" : "next-date"}>{isFollowUpOverdue(selected, today) ? "Debió contactarse" : "Próximo seguimiento"} <strong>{formatDate(selected.nextFollowUp)}</strong></div>}</DetailSection><button type="button" className="primary-button full-width" onClick={() => { setEditing(selected); setSelected(null); }}>Editar prospecto</button></aside></div>}
    {meetingOpen && <div className="overlay" onClick={() => setMeetingOpen(false)}><aside className="meeting-panel" onClick={(event) => event.stopPropagation()}><div className="panel-heading"><div><div className="eyebrow">Google Calendar + Meet</div><h2>Nueva reunión</h2></div><button className="close-button" onClick={() => setMeetingOpen(false)}>×</button></div>{!google.connected ? <div className="connect-prompt"><div className="teams-logo">G</div><h3>Conecta tu cuenta de Google</h3><p>El evento se creará directamente en tu Google Calendar y podrá incluir un enlace de Google Meet.</p><button className="primary-button" onClick={connectGoogle}>Conectar Google</button></div> : <form className="meeting-form" onSubmit={createMeeting}><label>Asunto<input name="subject" required defaultValue={meetingSubject(selected ?? undefined)} /></label><label>Correo del contacto<input type="email" name="attendeeEmail" defaultValue={selected?.email ?? ""} placeholder="contacto@empresa.com" /></label><label className="all-day-toggle"><input name="allDay" type="checkbox" /> Reunión de todo el día</label><label>Fecha<input name="date" type="date" required defaultValue={meetingDate} /></label><div className="two-fields"><label>Inicio<input name="start" type="datetime-local" defaultValue={meetingStart} /></label><label>Fin<input name="end" type="datetime-local" defaultValue={meetingEnd} /></label></div><p className="form-hint">Si eliges “todo el día”, las horas no son necesarias.</p><label>Notas para la reunión<textarea name="body" rows={4} defaultValue={meetingDescription(selected ?? undefined)} /></label><button className="primary-button full-width" type="submit">Crear evento en Google Calendar</button></form>}</aside></div>}
  </main>;
}

function Sidebar({ view, onNavigate, prospectCount, agendaCount, alertCount, googleConnected, demoMode, onConnect, onLogout, collapsed, expanded, onToggle, onMouseEnter, onMouseLeave }: { view: View; onNavigate: (view: View) => void; prospectCount: number; agendaCount: number; alertCount: number; googleConnected: boolean; demoMode: boolean; onConnect: () => void; onLogout: () => void | Promise<void>; collapsed: boolean; expanded: boolean; onToggle: () => void; onMouseEnter: () => void; onMouseLeave: () => void }) {
  const items: { view: View; label: string; icon: IconName; count?: number; alert?: boolean }[] = [
    { view: "pipeline", label: "Embudo", icon: "grid", count: prospectCount },
    { view: "agenda", label: "Agenda", icon: "calendar", count: agendaCount, alert: true },
    { view: "alerts", label: "Alertas", icon: "alert", count: alertCount, alert: true },
  ];
  return <aside className={`sidebar ${collapsed ? "collapsed" : ""} ${expanded ? "is-expanded" : ""}`} onMouseEnter={onMouseEnter} onMouseLeave={onMouseLeave}><div className="sidebar-surface" onMouseEnter={onMouseEnter} onMouseLeave={onMouseLeave}><div className="brand"><span className="brand-mark">V</span><span className="brand-copy"><strong>VPA</strong><small>CRM comercial</small></span><button className="sidebar-toggle" type="button" onClick={onToggle} aria-label={collapsed ? "Expandir barra lateral" : "Contraer barra lateral"} aria-expanded={!collapsed} title={collapsed ? "Expandir barra lateral" : "Contraer barra lateral"}><UiIcon name="panel" size={18} /></button></div><div className="workspace-label">ESPACIO DE TRABAJO</div><nav className="sidebar-nav" aria-label="Espacio de trabajo">{items.map((item) => <button key={item.view} className={view === item.view ? "nav-item active" : "nav-item"} onClick={() => onNavigate(item.view)} aria-current={view === item.view ? "page" : undefined} aria-label={item.label} data-tooltip={!expanded ? item.label : undefined}><UiIcon name={item.icon} size={18} /><span className="nav-label">{item.label}</span>{item.count !== undefined && <b className={item.alert ? "nav-count nav-alert" : "nav-count"}>{expanded ? item.count.toLocaleString("es-MX") : item.count > 99 ? "" : item.count}</b>}</button>)}</nav><div className="sidebar-bottom"><div className="connection-card"><div className="connection-heading"><span className={googleConnected ? "connected-dot" : "offline-dot"} /><span className="connection-label">Google Workspace</span></div><p>{googleConnected ? "Cuenta conectada" : demoMode ? "Modo demo local" : "Conecta Calendar y Meet"}</p><button className="connection-button" title={googleConnected || demoMode ? "Cerrar sesión" : "Conectar Google"} aria-label={googleConnected || demoMode ? "Cerrar sesión" : "Conectar Google"} onClick={googleConnected || demoMode ? onLogout : onConnect}>{googleConnected || demoMode ? <><span className="connection-action-label">Cerrar sesión</span><UiIcon name="logout" size={14} /></> : <span className="connection-action-label">Conectar Google</span>}</button></div><div className="user-chip"><span className="user-avatar">SP</span><span className="user-details"><strong>{googleConnected ? "Cuenta de Google" : "Sesión demo"}</strong><small>{googleConnected ? "Calendario conectado" : "Datos locales"}</small></span><button className="logout-emoji" title="Cerrar sesión" aria-label="Cerrar sesión" onClick={onLogout}><UiIcon name="logout" size={15} /></button></div></div></div></aside>;
}

function CommandPalette({ query, onQueryChange, items, activeIndex, onActiveIndex, onSelect, onClose }: { query: string; onQueryChange: (value: string) => void; items: CommandItem[]; activeIndex: number; onActiveIndex: (index: number) => void; onSelect: (item: CommandItem) => void; onClose: () => void }) {
  const inputRef = useRef<HTMLInputElement>(null);
  useEffect(() => { inputRef.current?.focus(); }, []);
  return <div className="command-overlay" onMouseDown={onClose}><section className="command-palette" role="dialog" aria-modal="true" aria-label="Buscar en VPA" onMouseDown={(event) => event.stopPropagation()}><div className="command-search"><UiIcon name="search" size={18} /><input ref={inputRef} value={query} onChange={(event) => onQueryChange(event.target.value)} placeholder="Buscar prospecto, empresa, correo..." aria-label="Buscar prospecto, empresa, correo" /><kbd>ESC</kbd></div><div className="command-results">{items.length ? items.map((item, index) => <button type="button" key={item.kind === "prospect" ? item.prospect.id : item.view} className={index === activeIndex ? "command-item active" : "command-item"} onMouseEnter={() => onActiveIndex(index)} onClick={() => onSelect(item)}><span className="command-item-icon"><UiIcon name={item.kind === "prospect" ? "grid" : item.view === "agenda" ? "calendar" : item.view === "alerts" ? "alert" : "grid"} size={16} /></span><span><strong>{item.label}</strong><small>{item.meta}</small></span><span className="command-item-hint">{item.kind === "navigation" ? "Ir" : "Abrir"}</span></button>) : <div className="command-empty">No encontramos resultados con esa búsqueda.</div>}</div><footer className="command-footer"><span><kbd>↑</kbd><kbd>↓</kbd> navegar</span><span><kbd>↵</kbd> seleccionar</span><span><kbd>Esc</kbd> cerrar</span></footer></section></div>;
}

function NewProspectModal({ onClose, onCreate, industries, initialProspect }: { onClose: () => void; onCreate: (prospect: Prospect) => void; industries: string[]; initialProspect?: Prospect }) {
  const [followUpDate, setFollowUpDate] = useState(initialProspect?.nextFollowUp ?? "");
  const initialPhone = splitPhone(initialProspect?.phone);
  const [phoneCountryCode, setPhoneCountryCode] = useState(initialPhone.countryCode);
  const industryOptions = Array.from(new Set([initialProspect?.industry, ...industries].filter(Boolean) as string[]));
  function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = new FormData(event.currentTarget); const company = String(form.get("company") || "").trim(); if (!company) return; onCreate({ id: initialProspect?.id ?? `manual-${Date.now()}`, company, tradeName: String(form.get("tradeName") || "").trim() || undefined, contact: String(form.get("contact") || "").trim() || undefined, email: String(form.get("email") || "").trim() || undefined, phone: storedPhone(String(form.get("phoneCountryCode") || "+52"), String(form.get("phone") || "")), website: String(form.get("website") || "").trim() || undefined, location: String(form.get("location") || "").trim() || undefined, industry: String(form.get("industry") || "Por clasificar"), priority: String(form.get("priority") || "media") as Prospect["priority"], stage: String(form.get("stage") || "clientes recibidos") as PipelineStage, nextFollowUp: followUpDate || undefined, waitingReason: String(form.get("waitingReason") || "").trim() || undefined, notes: String(form.get("notes") || "").trim() || undefined, source: initialProspect?.source ?? "Captura manual", lastInteraction: initialProspect?.lastInteraction }); }
  return <div className="overlay" onClick={onClose}><aside className="new-prospect-panel" onClick={(event) => event.stopPropagation()}><div className="panel-heading"><div><div className="eyebrow">{initialProspect ? "Actualizar oportunidad" : "Alta de oportunidad"}</div><h2>{initialProspect ? "Editar prospecto" : "Nuevo prospecto"}</h2><p className="form-intro">Captura el contexto una sola vez para que el seguimiento no se pierda.</p></div><button type="button" className="close-button" onClick={onClose}>×</button></div><form className="new-prospect-form" onSubmit={submit}><div className="form-section"><h3>Empresa</h3><div className="form-grid"><label>Razón social *<input name="company" required defaultValue={initialProspect?.company ?? ""} placeholder="Empresa legal" autoFocus /></label><label>Nombre comercial<input name="tradeName" defaultValue={initialProspect?.tradeName ?? ""} placeholder="Marca o nombre público" /></label><label>Industria<select name="industry" defaultValue={initialProspect?.industry ?? industryOptions[0] ?? "Por clasificar"}>{industryOptions.map((industry) => <option key={industry}>{industry}</option>)}<option>Por clasificar</option></select></label><label>Ubicación<input name="location" defaultValue={initialProspect?.location ?? ""} placeholder="Ciudad, estado o país" /></label></div></div><div className="form-section"><h3>Contacto principal</h3><div className="form-grid"><label>Nombre y puesto<input name="contact" defaultValue={initialProspect?.contact ?? ""} placeholder="Nombre de la persona decisora" /></label><label>Teléfono / extensión<div className="phone-input-group"><select name="phoneCountryCode" value={phoneCountryCode} onChange={(event) => setPhoneCountryCode(event.target.value)} aria-label="Lada internacional">{countryCodes.map((item) => <option key={item.code} value={item.code}>{item.code} · {item.country}</option>)}</select><input name="phone" defaultValue={initialPhone.number} placeholder="999 000 0000 ext. 123" /></div></label><label>Correo electrónico<input name="email" type="email" defaultValue={initialProspect?.email ?? ""} placeholder="contacto@empresa.com" /></label><label>Sitio web<input name="website" type="url" defaultValue={initialProspect?.website ?? ""} placeholder="https://" /></label></div></div><div className="form-section"><h3>Seguimiento comercial</h3><div className="form-grid"><label>Etapa<select name="stage" defaultValue={initialProspect?.stage ?? "clientes recibidos"}>{pipelineStages.map((stage) => <option key={stage} value={stage}>{stageLabels[stage]}</option>)}</select></label><label>Prioridad<select name="priority" defaultValue={initialProspect?.priority ?? "media"}><option value="alta">Alta</option><option value="media">Media</option><option value="baja">Baja</option></select></label><label>Próximo seguimiento<DatePickerField value={followUpDate} onChange={setFollowUpDate} /></label><label>Motivo de espera<input name="waitingReason" defaultValue={initialProspect?.waitingReason ?? ""} placeholder="Ej. esperar a que seamos banco" /></label><label className="form-full">Notas iniciales<textarea name="notes" defaultValue={initialProspect?.notes ?? ""} rows={4} placeholder="De dónde viene, qué necesita y cuál es el siguiente paso..." /></label></div></div><div className="new-prospect-footer"><button type="button" className="ghost-button" onClick={onClose}>Cancelar</button><button type="submit" className="primary-button">{initialProspect ? "Guardar cambios" : "Crear prospecto"}</button></div></form></aside></div>;
}

function DatePickerField({ value, onChange }: { value: string; onChange: (value: string) => void }) {
  const initialDate = value ? new Date(`${value}T12:00:00`) : new Date();
  const [open, setOpen] = useState(false);
  const [viewDate, setViewDate] = useState(initialDate);
  const monthLabel = new Intl.DateTimeFormat("es-MX", { month: "long", year: "numeric" }).format(viewDate);
  function moveMonth(offset: number) { setViewDate((current) => new Date(current.getFullYear(), current.getMonth() + offset, 1)); }
  function chooseDay(day: number, baseDate = viewDate) { const selectedDate = new Date(baseDate.getFullYear(), baseDate.getMonth(), day); onChange(`${selectedDate.getFullYear()}-${String(selectedDate.getMonth() + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`); setOpen(false); }
  return <div className="date-picker"><button type="button" className="date-picker-trigger" onClick={() => { if (!open) setViewDate(value ? new Date(`${value}T12:00:00`) : new Date()); setOpen((current) => !current); }}><span>▣</span>{value ? formatDate(value) : "Elegir fecha"}</button>{open && <div className="date-picker-popover"><div className="date-picker-header"><button type="button" aria-label="Mes anterior" onClick={() => moveMonth(-1)}>‹</button><strong>{monthLabel}</strong><button type="button" aria-label="Mes siguiente" onClick={() => moveMonth(1)}>›</button></div><div className="date-picker-weekdays">{weekDays.map((day, index) => <span key={`${day}-${index}`}>{day}</span>)}</div><div className="date-picker-grid">{calendarDays(viewDate.getFullYear(), viewDate.getMonth()).map((day, index) => day ? <button type="button" key={day} className={value === `${viewDate.getFullYear()}-${String(viewDate.getMonth() + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}` ? "selected-day" : ""} onClick={() => chooseDay(day)}>{day}</button> : <span key={`empty-${index}`} />)}</div><button type="button" className="date-picker-today" onClick={() => { const now = new Date(); setViewDate(now); chooseDay(now.getDate(), now); }}>Hoy</button></div>}</div>;
}

function ProspectCard({ prospect, overdue, onClick, onDragStart, onDragEnd }: { prospect: Prospect; overdue: boolean; onClick: () => void; onDragStart: (event: React.DragEvent<HTMLButtonElement>) => void; onDragEnd: () => void }) { return <button draggable className={`prospect-card priority-card-${prospect.priority}${overdue ? " overdue-card" : ""}`} onClick={onClick} onDragStart={onDragStart} onDragEnd={onDragEnd}><div className="card-top"><span className={`priority priority-${prospect.priority}`}>{priorityLabel(prospect.priority)}</span><span className="card-menu" aria-label="Arrastrar para cambiar de etapa">⠿</span></div><div className="company-row"><span className="avatar">{initials(prospect.company)}</span><span className="company-name">{prospect.tradeName ?? prospect.company}</span></div><div className="company-legal">{prospect.company}</div><div className="card-meta"><span>{prospect.industry}</span>{prospect.phone && <span>☎ {formatPhone(prospect.phone)}</span>}{prospect.email && <span>✉ {prospect.email}</span>}</div>{prospect.recordCount && prospect.recordCount > 1 && <div className="consolidated-tag">{prospect.recordCount} registros consolidados · {prospect.locationCount ?? 0} ubicaciones</div>}{prospect.nextFollowUp && <div className={overdue ? "follow-up overdue-follow-up" : "follow-up"}><span>{overdue ? "⚠" : "↗"}</span> {overdue ? "Seguimiento vencido · " : ""}{formatDate(prospect.nextFollowUp)}</div>}{prospect.waitingReason && <div className="waiting-reason">{prospect.waitingReason}</div>}</button>; }
function DetailSection({ title, children }: { title: string; children: ReactNode }) { return <div className="detail-section"><h3>{title}</h3>{children}</div>; }
function DetailRow({ label, value }: { label: string; value: string }) { return <div className="detail-row"><dt>{label}</dt><dd>{value}</dd></div>; }
function AgendaView({ connected, events, month, onConnect, onCreate, onMonthChange, onMoveEvent }: { connected: boolean; events: CalendarEvent[]; month: Date; onConnect: () => void; onCreate: (date?: string) => void; onMonthChange: (date: Date) => void; onMoveEvent: (eventId: string, date: string, time?: string) => void }) {
  const [mode, setMode] = useState<CalendarViewMode>("month");
  const title = mode === "month" ? new Intl.DateTimeFormat("es-MX", { month: "long", year: "numeric" }).format(month) : mode === "week" ? `Semana del ${formatDate(localDateKey(localWeekStart(month)))}` : new Intl.DateTimeFormat("es-MX", { weekday: "long", day: "numeric", month: "long", year: "numeric" }).format(month);
  function navigate(direction: number) { const next = new Date(month); if (mode === "month") next.setMonth(next.getMonth() + direction); else next.setDate(next.getDate() + direction * (mode === "week" ? 7 : 1)); onMonthChange(next); }
  function selectDay(date: string) { setMode("day"); onMonthChange(new Date(`${date}T12:00:00`)); }
  const weekDaysForView = Array.from({ length: 7 }, (_, index) => { const start = localWeekStart(month); start.setDate(start.getDate() + index); return start; });
  return <div className="module-page"><div className="module-header"><div><p className="hero-title">Tu calendario, dentro del seguimiento.</p><p className="hero-subtitle">Consulta tus reuniones reales y crea citas desde un día o una hora.</p></div><button className="primary-button" onClick={() => onCreate()}>+ Nueva reunión</button></div>{!connected ? <EmptyIntegration icon="◷" title="Conecta tu Google Calendar" text="Podrás ver tu agenda y crear reuniones con enlace de Google Meet desde el CRM." action="Conectar Google" onClick={onConnect} /> : <div className="calendar-layout single-calendar"><div className="calendar-card calendar-main"><div className="calendar-card-head calendar-toolbar"><div className="calendar-nav"><button type="button" onClick={() => navigate(-1)}>‹</button><button type="button" onClick={() => onMonthChange(new Date())}>Hoy</button><button type="button" onClick={() => navigate(1)}>›</button></div><h3>{title}</h3><div className="calendar-view-switcher"><button className={mode === "day" ? "active" : ""} onClick={() => setMode("day")}>Día</button><button className={mode === "week" ? "active" : ""} onClick={() => setMode("week")}>Semana</button><button className={mode === "month" ? "active" : ""} onClick={() => setMode("month")}>Mes</button></div></div>{mode === "month" ? <MonthCalendar month={month} events={events} onSelectDay={selectDay} onMoveEvent={onMoveEvent} /> : <TimeGridCalendar days={mode === "week" ? weekDaysForView : [month]} events={events} onCreate={onCreate} onMoveEvent={onMoveEvent} />}</div></div>}</div>; }

function localDateKey(date: Date) { return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`; }
function localWeekStart(date: Date) { const start = new Date(date.getFullYear(), date.getMonth(), date.getDate()); start.setDate(start.getDate() - ((start.getDay() + 6) % 7)); return start; }
function eventDateKey(event: CalendarEvent) { return event.start?.date || event.start?.dateTime?.slice(0, 10); }
function openCalendarEvent(event: CalendarEvent) { window.open(event.onlineMeeting?.joinUrl || event.webLink || "#", "_blank", "noopener,noreferrer"); }
function CalendarEventChip({ event, onMoveStart }: { event: CalendarEvent; onMoveStart: (event: React.DragEvent<HTMLButtonElement>) => void }) { return <button type="button" draggable className={event.allDay ? "calendar-event all-day" : "calendar-event"} onDragStart={onMoveStart} onClick={(click) => { click.stopPropagation(); openCalendarEvent(event); }} title="Arrastra para mover este evento"><strong>{event.allDay ? "Todo el día" : formatDateTime(event.start?.dateTime)}</strong><span>{event.subject || "Sin asunto"}</span></button>; }
function MonthCalendar({ month, events, onSelectDay, onMoveEvent }: { month: Date; events: CalendarEvent[]; onSelectDay: (date: string) => void; onMoveEvent: (eventId: string, date: string, time?: string) => void }) { const year = month.getFullYear(); const monthIndex = month.getMonth(); const firstDay = (new Date(year, monthIndex, 1).getDay() + 6) % 7; const daysInMonth = new Date(year, monthIndex + 1, 0).getDate(); return <><div className="calendar-weekdays">{weekDays.map((day, index) => <span key={`${day}-${index}`}>{day}</span>)}</div><div className="calendar-grid">{Array.from({ length: firstDay }, (_, index) => <div className="calendar-day empty" key={`empty-${index}`} />)}{Array.from({ length: daysInMonth }, (_, index) => { const date = localDateKey(new Date(year, monthIndex, index + 1)); const dayEvents = events.filter((event) => eventDateKey(event) === date); return <div className="calendar-day" key={date} onClick={() => onSelectDay(date)} onDragOver={(event) => event.preventDefault()} onDrop={(event) => { event.preventDefault(); const id = event.dataTransfer.getData("text/calendar-event"); if (id) onMoveEvent(id, date); }}><span className="calendar-day-number">{index + 1}</span>{dayEvents.slice(0, 4).map((event) => <CalendarEventChip key={event.id} event={event} onMoveStart={(drag) => drag.dataTransfer.setData("text/calendar-event", event.id)} />)}{dayEvents.length > 4 && <small className="calendar-more">+{dayEvents.length - 4} más</small>}</div>; })}</div></>; }
function TimeGridCalendar({ days, events, onCreate, onMoveEvent }: { days: Date[]; events: CalendarEvent[]; onCreate: (date?: string) => void; onMoveEvent: (eventId: string, date: string, time?: string) => void }) { const hours = Array.from({ length: 24 }, (_, index) => index); return <div className={`time-calendar time-calendar-${days.length}`}><div className="time-grid-header"><span />{days.map((day) => <strong key={localDateKey(day)}>{new Intl.DateTimeFormat("es-MX", { weekday: "short", day: "numeric" }).format(day)}</strong>)}</div><div className="time-grid-all-day"><span>Todo el día</span>{days.map((day) => { const date = localDateKey(day); return <div key={date} onClick={() => onCreate(`${date}T09:00`)}>{events.filter((event) => event.allDay && eventDateKey(event) === date).map((event) => <CalendarEventChip key={event.id} event={event} onMoveStart={(drag) => drag.dataTransfer.setData("text/calendar-event", event.id)} />)}</div>; })}</div><div className="time-grid-body">{hours.map((hour) => <div className="time-grid-row" key={hour}><span className="time-label">{String(hour).padStart(2, "0")}:00</span>{days.map((day) => { const date = localDateKey(day); const time = `${String(hour).padStart(2, "0")}:00`; const timedEvents = events.filter((event) => !event.allDay && eventDateKey(event) === date && Number(event.start?.dateTime?.slice(11, 13)) === hour); return <div className="time-slot" key={`${date}-${hour}`} onClick={() => onCreate(`${date}T${time}`)} onDragOver={(event) => event.preventDefault()} onDrop={(event) => { event.preventDefault(); const id = event.dataTransfer.getData("text/calendar-event"); if (id) onMoveEvent(id, date, time); }}>{timedEvents.map((calendarEvent) => <CalendarEventChip key={calendarEvent.id} event={calendarEvent} onMoveStart={(drag) => drag.dataTransfer.setData("text/calendar-event", calendarEvent.id)} />)}</div>; })}</div>)}</div></div>; }
function AlertsView({ connected, alerts, onConnect }: { connected: boolean; alerts: { prospect: Prospect; reason: string }[]; onConnect: () => void }) { if (!connected) return <div className="module-page"><div className="module-header"><div><p className="hero-title">Que ningún cliente se enfríe.</p><p className="hero-subtitle">Las alertas se basan en la próxima acción y en la última interacción.</p></div></div><EmptyIntegration icon="!" title="Conecta Google para activar alertas" text="Después podremos enviar recordatorios mediante el canal de Google que elijas." action="Conectar Google" onClick={onConnect} /></div>; return <div className="module-page"><div className="module-header"><div><p className="hero-title">Clientes descuidados.</p><p className="hero-subtitle">Regla actual: seguimiento vencido, sin próxima acción o sin interacción en 14 días.</p></div></div><div className="alert-grid"><div className="alert-rule-card"><span className="alert-icon">!</span><div><strong>Reglas activas</strong><p>Seguimiento vencido · sin próxima acción · sin interacción reciente</p></div><b>{alerts.length}</b></div>{alerts.length ? alerts.map(({ prospect, reason }) => <div className="neglected-card" key={prospect.id}><div className="neglected-card-top"><span className={`priority priority-${prospect.priority}`}>{priorityLabel(prospect.priority)}</span><span className="neglect-label">{reason}</span></div><strong>{prospect.tradeName ?? prospect.company}</strong><p>{prospect.contact || "Contacto pendiente"} · {formatPhone(prospect.phone) || prospect.email || "Sin dato de contacto"}</p><small>{prospect.nextFollowUp ? `Seguimiento: ${formatDate(prospect.nextFollowUp)}` : "No tiene próxima acción"}</small></div>) : <div className="no-data">No hay clientes descuidados con las reglas actuales.</div>}</div></div>; }
function EmptyIntegration({ icon, title, text, action, onClick }: { icon: string; title: string; text: string; action: string; onClick: () => void }) { return <div className="integration-empty"><span className="integration-icon">{icon}</span><h2>{title}</h2><p>{text}</p><button className="primary-button" onClick={onClick}>{action}</button><small>Permisos actuales: perfil básico de Google · eventos de Calendar</small></div>; }
function AuthScreen({ loading, configured, missing, redirectUri, notice, onConnect, onDemo }: { loading?: boolean; configured?: boolean; missing?: string[]; redirectUri?: string; notice?: { kind: "success" | "warning" | "error"; text: string } | null; onConnect?: () => void; onDemo?: () => void }) {
  return <main className="auth-screen"><div className="auth-card"><div className="auth-brand"><span className="brand-mark">V</span><div><strong>VPA</strong><small>CRM comercial</small></div></div>{loading ? <><div className="auth-spinner" /><h1>Preparando tu espacio</h1><p>Comprobando la sesión de Google…</p></> : <><div className="auth-eyebrow">ESPACIO DE TRABAJO PRIVADO</div><h1>Bienvenido a VPA CRM</h1><p className="auth-lead">Inicia sesión con Google para entrar a tu embudo, agenda y seguimiento comercial.</p><button className="google-login-button" onClick={onConnect}><span className="google-g">G</span> Continuar con Google</button><button className="demo-login-button" onClick={onDemo}>👀 Ver demo local</button>{notice && <div className={`auth-notice ${notice.kind}`} role="status">{notice.text}</div>}{!configured && <div className="auth-setup"><strong>Google aún no está conectado</strong><span>Faltan {(missing ?? ["GOOGLE_CLIENT_ID", "GOOGLE_CLIENT_SECRET"]).join(" y ")}.</span><small>Registra esta URI en Google Cloud:</small><code>{redirectUri || "http://localhost:3000/api/google/callback"}</code></div>}<p className="auth-footnote">El modo demo solo usa los datos locales importados y no conecta ningún servicio externo.</p></>}</div></main>;
}
